expect(bool(bits([&](char16_t c){return m::matchMoPattern(kind,std::u16string(1,c)+units({65}));})==expand({{16,'0'},{1,'e'},{5,'f'},{1,'7'},{1,'0'},{1,'e'},{5,'f'},{1,'7'},{16353,'0'}})));
